//! Conformance testing suites for downstream consumer contracts.

pub mod mrs_consumer;

use mdc_core::{BookKind, IntegrityAlert, Symbol};
use std::collections::{HashMap, HashSet};

use crate::sink::RecordedEvent;

pub use mrs_consumer::{MrsConsumerHarness, MrsConsumerStats};

/// Report generated by the embedder conformance validator.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ConformanceReport {
    /// Total number of events verified.
    pub total_events: usize,
    /// Total number of order book snapshots verified.
    pub snapshots_verified: usize,
    /// Total number of order book deltas verified.
    pub deltas_verified: usize,
    /// Total number of trades verified.
    pub trades_verified: usize,
    /// Total number of book tickers verified.
    pub tickers_verified: usize,
    /// Total number of reference rates verified.
    pub reference_rates_verified: usize,
    /// Total number of integrity alerts verified.
    pub alerts_verified: usize,
}

/// Validates recorded streaming events against streaming sink and lifecycle conformance rules.
///
/// Checks:
/// - No `level` outside of `begin_book` / `end_book`.
/// - No nested or unclosed `begin_book`.
/// - No market data (`Level`, `Delta`, `Trade`, `BookTicker`) for a symbol between its
///   stale-marking alert and the next snapshot / `ResyncCompleted`.
/// - Alert ordering consistency.
pub fn validate(events: &[RecordedEvent]) -> Result<ConformanceReport, String> {
    let mut report = ConformanceReport::default();
    let mut in_book: HashMap<Symbol, BookKind> = HashMap::new();
    let mut stale_symbols: HashSet<Symbol> = HashSet::new();

    for (idx, event) in events.iter().enumerate() {
        report.total_events += 1;
        match event {
            RecordedEvent::BeginBook { symbol, kind } => {
                if in_book.contains_key(symbol) {
                    return Err(format!(
                        "Event {idx}: Nested BeginBook for {symbol} without EndBook"
                    ));
                }
                in_book.insert(symbol.clone(), *kind);

                match kind {
                    BookKind::Snapshot => {
                        stale_symbols.remove(symbol);
                        report.snapshots_verified += 1;
                    }
                    BookKind::Delta => {
                        if stale_symbols.contains(symbol) {
                            return Err(format!(
                                "Event {idx}: Delta received for {symbol} while stale before snapshot"
                            ));
                        }
                        report.deltas_verified += 1;
                    }
                }
            }

            RecordedEvent::Level { .. } => {
                // Must be inside begin_book/end_book
                if in_book.is_empty() {
                    return Err(format!(
                        "Event {idx}: Level received outside of BeginBook/EndBook"
                    ));
                }
            }

            RecordedEvent::EndBook { symbol, .. } => {
                if in_book.remove(symbol).is_none() {
                    return Err(format!(
                        "Event {idx}: EndBook for {symbol} without matching BeginBook"
                    ));
                }
            }

            RecordedEvent::Trade { symbol, .. } => {
                if stale_symbols.contains(symbol) {
                    return Err(format!(
                        "Event {idx}: Trade received for {symbol} while stale before snapshot/resync"
                    ));
                }
                report.trades_verified += 1;
            }

            RecordedEvent::BookTicker { symbol, .. } => {
                if stale_symbols.contains(symbol) {
                    return Err(format!(
                        "Event {idx}: BookTicker received for {symbol} while stale before snapshot/resync"
                    ));
                }
                report.tickers_verified += 1;
            }

            RecordedEvent::ReferenceRate { .. } => {
                report.reference_rates_verified += 1;
            }

            RecordedEvent::Alert { symbol, alert } => {
                report.alerts_verified += 1;
                match alert {
                    IntegrityAlert::ResyncCompleted { .. } => {
                        stale_symbols.remove(symbol);
                    }
                    IntegrityAlert::ResyncStarted
                    | IntegrityAlert::GapDetected { .. }
                    | IntegrityAlert::ChecksumMismatch { .. }
                    | IntegrityAlert::SilenceTimeout { .. }
                    | IntegrityAlert::ConnectionLost { .. }
                    | IntegrityAlert::SourceError { .. }
                    | IntegrityAlert::Quarantined { .. } => {
                        stale_symbols.insert(symbol.clone());
                    }
                    _ => {}
                }
            }
        }
    }

    if let Some((sym, _)) = in_book.into_iter().next() {
        return Err(format!(
            "Unclosed order book for symbol {sym} at end of event stream"
        ));
    }

    Ok(report)
}

/// Runs conformance assertions against recorded streaming sink events, panicking on violation.
pub fn run(events: &[RecordedEvent]) -> ConformanceReport {
    validate(events).unwrap_or_else(|err| panic!("Conformance violation: {err}"))
}
